import { renderLegend } from "./renderLegend";
import { getLineLegendItems } from "../../lineChart/getLineLegendItems";
import { getBarLegendItems } from "../../barChart/getBarLegendItems";
import { getPieLegendItems } from "../../pieChart/getPieLegendItems";
export const LEGEND_PLUGIN_ID = "zenithLegend";
export const legendPlugin = (containerId, options, isDrive, isHidden, toggleHidden) => ({
    id: LEGEND_PLUGIN_ID,
    isDrive: isDrive,
    afterUpdate(chart) {
        const container = document.getElementById(containerId);
        if (!container) {
            return;
        }
        if (options === false) {
            container.classList.add("zen-legend--hidden");
            return;
        }
        container.innerHTML = "";
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const chartType = chart.config.type;
        let items = [];
        if (chartType === "line") {
            items = getLineLegendItems(chart.data, options);
        }
        if (chartType === "bar") {
            items = getBarLegendItems(chart.data);
        }
        if (chartType === "pie") {
            items = getPieLegendItems(chart.data, options, isHidden);
        }
        items = items.map(item => {
            const onClick = () => {
                toggleHidden(item.index);
                chart.update();
            };
            return Object.assign(Object.assign({}, item), { onClick, hidden: isHidden(item.index) });
        });
        if (items.length === 0) {
            container.classList.add("zen-legend--hidden");
            return;
        }
        container.classList.remove("zen-legend--hidden");
        renderLegend(container, this.isDrive, items);
    }
});
